export default {"id":"launchkey-level-18","number":18,"title":"Appendices","skillBand":"Textbook","duration":"From the course textbook","summary":"This appendix provides the technical reference specifications extracted from the official Novation Launchkey MK4 Programmer's Reference Guide. It is designed for developers authoring custom control scripts, Max for Live devices, or advanced","modules":[{"id":"launchkey-m-1-1","code":"1","title":"Appendices — Reference & Advanced Technical Protocols","blurb":"This appendix provides the technical reference specifications extracted from the official Novation Launchkey MK4 Programmer's Reference Guide. It is designed for developers authoring custom control scripts, Max for Live devices, or advanced","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-58","title":"Section overview","blocks":[{"type":"step","title":"Appendix A — Programmer’s Reference & MIDI Protocol","blocks":[{"type":"heading","text":"Overview","level":3},{"type":"prose","html":"This appendix provides the technical reference specifications extracted from the official <strong>Novation Launchkey MK4 Programmer's Reference Guide</strong>. It is designed for developers authoring custom control scripts, Max for Live devices, or advanced MIDI routing routines."}]}],"minutes":8},{"id":"launchkey-l-a-1-1","title":"A.1.1: The Dual Logical Interface Protocol","blocks":[{"type":"step","title":"A.1.1: The Dual Logical Interface Protocol","blocks":[{"type":"prose","html":"The Launchkey MK4 61 exposes two USB MIDI endpoints:"},{"type":"list","items":["<strong>Interface 1 (Performing Interface)</strong>:","Carries performance data: Keybed Note On/Off, Pitch Bend (14-bit), Modulation (CC 1), Custom Mode Encoders, Custom Mode Faders, Custom Mode Pads, Drum Mode (Channel 10), Chord Engines (Channel 3).","<strong>Interface 2 (DAW Interface)</strong>:","Carries bidirectional DAW control surface protocol: Clip launching SysEx, track volume/pan automation, OLED display text injection, transport commands, and mode feedback."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-a-1-2","title":"A.1.2: Standalone Mode (Channel 16 Telemetry)","blocks":[{"type":"step","title":"A.1.2: Standalone Mode (Channel 16 Telemetry)","blocks":[{"type":"prose","html":"Upon power-on before a host DAW handshake:"},{"type":"list","items":["The controller operates in <strong>Standalone Mode</strong>.","DAW transport and workflow buttons transmit standard MIDI Continuous Controller (CC) messages on <strong>MIDI Channel 16</strong>.","The hardware <code>Play</code> and <code>Stop</code> buttons transmit standard <strong>MIDI Real Time Start (<code>0xFA</code>)</strong> and <strong>MIDI Real Time Stop (<code>0xFC</code>)</strong> system real-time bytes."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-a-1-3","title":"A.1.3: Entering and Exiting DAW Mode Handshake","blocks":[{"type":"step","title":"A.1.3: Entering and Exiting DAW Mode Handshake","blocks":[{"type":"prose","html":"Host software engages native DAW integration by transmitting a dedicated 3-byte MIDI handshake message to <strong>Interface 2 (DAW In)</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    DAW MODE ENGAGEMENT HANDSHAKE (INTERFACE 2)                |\n+-------------------+---------------------------+-------------------------------+\n| Command           | Hexadecimal Byte Sequence | Decimal Representation        |\n+-------------------+---------------------------+-------------------------------+\n| **Enter DAW Mode**| `9F 0C 7F`                | Note On, Ch 16, Note 12, V=127|\n| **Exit DAW Mode** | `9F 0C 00`                | Note On, Ch 16, Note 12, V=0  |\n+-------------------+---------------------------+-------------------------------+</pre>"},{"type":"prose","html":"<em>Microcontroller Response</em>: Receiving <code>9F 0C 7F</code> illuminates DAW-native pads (Plugin, Mixer, Sends, Transport, DAW Clips) and activates the bidirectional OLED display protocol."}]}],"minutes":8},{"id":"launchkey-l-a-1-4","title":"A.1.4: Hardware Mode Report Continuous Controllers","blocks":[{"type":"step","title":"A.1.4: Hardware Mode Report Continuous Controllers","blocks":[{"type":"prose","html":"When operating in DAW Mode, the Launchkey MK4 reports mode changes to the host via <strong>MIDI Channel 7</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    HARDWARE MODE REPORT CC MATRIX (CHANNEL 7)                 |\n+---------------+---------------+-----------------------------------------------+\n| Continuous CC | Hardware Plane| Reported Value Table                          |\n+---------------+---------------+-----------------------------------------------+\n| **CC 29**     | **Pad Mode**  | 0: DAW Clips (1/2) \\| 1: Step Sequencer (2/2) |\n|               |               | 2: Drum \\| 3: User Chord \\| 4: Arp Pattern    |\n|               |               | 5–8: Custom Modes 1–4                         |\n+---------------+---------------+-----------------------------------------------+\n| **CC 30**     | **Encoder**   | 0: Plugin \\| 1: Mixer \\| 2: Sends             |\n|               | **Mode**      | 3: Transport \\| 4–7: Custom Modes 1–4         |\n+---------------+---------------+-----------------------------------------------+\n| **CC 31**     | **Fader Mode**| 0: Volume \\| 1–4: Custom Modes 1–4            |\n+---------------+---------------+-----------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-a-1-5","title":"A.1.5: SysEx Header & Display Protocol","blocks":[{"type":"step","title":"A.1.5: SysEx Header & Display Protocol","blocks":[{"type":"prose","html":"System Exclusive (SysEx) communication follows the standard Novation manufacturer ID protocol:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">NOVATION LAUNCHKEY MK4 UNIVERSAL SYSEX HEADER:\nF0 00 20 29 02 18 [Command] [Payload Data...] F7\n\n- F0 00 20 29 : Novation Focusrite Manufacturer ID\n- 02 18       : Launchkey MK4 Regular SKU Product ID\n- F7          : End of Exclusive (EOX)</pre>"},{"type":"prose","html":"<em>(Warning: Do not use Launchkey Mini SysEx product IDs on the 61-key model).</em>"}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-2-2","code":"2","title":"Appendices — Reference & Advanced Technical Protocols","blurb":"This appendix establishes maintenance schedules, physical sensor calibration protocols, optical adjustments, and power management best practices to ensure long-term hardware reliability of the Launchkey MK4 61. - Routine Inspection: Connect","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-59","title":"Section overview","blocks":[{"type":"step","title":"Appendix B — Hardware Maintenance, Calibration & Health","blocks":[{"type":"heading","text":"Overview","level":3},{"type":"prose","html":"This appendix establishes maintenance schedules, physical sensor calibration protocols, optical adjustments, and power management best practices to ensure long-term hardware reliability of the Launchkey MK4 61."}]}],"minutes":8},{"id":"launchkey-l-b-1-1","title":"B.1.1: Firmware Maintenance Schedule","blocks":[{"type":"step","title":"B.1.1: Firmware Maintenance Schedule","blocks":[{"type":"list","items":["<strong>Routine Inspection</strong>: Connect the Launchkey to Novation Components (<code>components.novationmusic.com</code>) periodically.","<strong>Mandatory Flash Events</strong>: Always check for firmware updates:","Immediately following major host operating system upgrades (e.g., Windows feature updates, major macOS releases).","Following major Ableton Live point releases (e.g., Live 12.1, Live 12.2)."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-b-1-2","title":"B.1.2: Physical Wheel Calibration","blocks":[{"type":"step","title":"B.1.2: Physical Wheel Calibration","blocks":[{"type":"prose","html":"If the Pitch Wheel drifts from zero center or the Modulation Wheel fails to achieve full 0–127 travel:"},{"type":"list","items":["Open Novation Components -&gt; Click <code>User Menu</code> (top right).","Select <strong>Calibrate Wheels</strong>.","Follow the guided on-screen mechanical sweeps (Max Up, Max Down, Center Return).","Save the calibration to write updated offset lookup tables to non-volatile EEPROM."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-b-1-3","title":"B.1.3: Factory Reset Fallback","blocks":[{"type":"step","title":"B.1.3: Factory Reset Fallback","blocks":[{"type":"prose","html":"If firmware parameters become corrupt:"},{"type":"list","items":["In Components, navigate to <code>User Menu &gt; Factory Reset</code>.","<em>Consequences</em>:","Settings revert to defaults (Part A: Ch 1, Part B: Ch 2, Chords: Ch 3, Drums: Ch 10).","Custom Modes are cleared.","Mass Storage Device (MSD) / Easy Start is re-enabled."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-b-1-4","title":"B.1.4: Optical Telemetry Management","blocks":[{"type":"step","title":"B.1.4: Optical Telemetry Management","blocks":[{"type":"list","items":["In Settings, configure <code>LED Brightness</code> (1–10) and <code>Screen Brightness</code> (1–10).","Setting brightness to level <strong>6–8</strong> reduces internal power draw and extends OLED display lifespan in dark studio environments."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-b-1-5","title":"B.1.5: Standby Mode vs. Physical Disconnection","blocks":[{"type":"step","title":"B.1.5: Standby Mode vs. Physical Disconnection","blocks":[{"type":"list","items":["<strong>Standby Mode (<code>Shift + Settings</code> for 2 seconds)</strong>: Extinguishes LEDs while keeping MIDI active. Ideal during short tracking breaks.","<strong>Physical USB Disconnection</strong>: Recommended when powering down the studio for extended periods to prevent residual USB bus power drain."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-3-3","code":"3","title":"Appendices — Reference & Advanced Technical Protocols","blurb":"This appendix defines the pedagogical boundaries distinguishing this hardware course from sister disciplines in the music academy, while cataloging official documented knowledge gaps to prevent speculation or misinformation. To maintain rig","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-60","title":"Section overview","blocks":[{"type":"step","title":"Appendix C — Curricular Boundaries & Documented Gaps","blocks":[{"type":"heading","text":"Overview","level":3},{"type":"prose","html":"This appendix defines the pedagogical boundaries distinguishing this hardware course from sister disciplines in the music academy, while cataloging official documented knowledge gaps to prevent speculation or misinformation."}]}],"minutes":8},{"id":"launchkey-l-c-1-1","title":"C.1.1: Sister Course Boundaries","blocks":[{"type":"step","title":"C.1.1: Sister Course Boundaries","blocks":[{"type":"prose","html":"To maintain rigorous technical focus on the Launchkey MK4 61 hardware, related audio disciplines belong strictly to sister courses:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    ACADEMY CURRICULAR DOMAIN BOUNDARIES                       |\n+---------------------------+---------------------------------------------------+\n| Course Title              | Exclusive Pedagogical Domain                      |\n+---------------------------+---------------------------------------------------+\n| **Mastering Ableton Live**| DAW devices, audio warping, mixdown, arrangement  |\n| **Piano Playing Basics**  | Hand ergonomics, scales, acoustic piano technique |\n| **Drums &amp; Rhythm**        | Polyrhythmic programming, groove theory, sound des|\n| **Sound Design**          | Subtractive/FM synthesis, filter modulation       |\n| **Foundations of DJ'ing** | DJ transitions, cueing, live deck performance     |\n+---------------------------+---------------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-c-1-2","title":"C.1.2: Documented Knowledge Gaps & Hardware Truths","blocks":[{"type":"step","title":"C.1.2: Documented Knowledge Gaps & Hardware Truths","blocks":[{"type":"prose","html":"In adherence to the strict grounding rule:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    DOCUMENTED HARDWARE GAPS &amp; REALITIES                       |\n+---------------------------+---------------------------------------------------+\n| Item / Specification      | Authoritative Technical Fact                      |\n+---------------------------+---------------------------------------------------+\n| **Propellerhead Reason**  | Listed on marketing overview; NO published step   |\n|                           | procedure in 61 DAW User Guide -&gt; `{type: 'gap'}` |\n+---------------------------+---------------------------------------------------+\n| **Ardour DAW**            | Listed on marketing overview; NO published step   |\n|                           | procedure in 61 DAW User Guide -&gt; `{type: 'gap'}` |\n+---------------------------+---------------------------------------------------+\n| **Expression Pedal**      | The 6.35 mm jack supports ONLY momentary binary   |\n|                           | switches. Expression pedals are UNSUPPORTED.      |\n+---------------------------+---------------------------------------------------+\n| **MIDI In Jack**          | The 61 contains 5-pin MIDI OUT only. Zero MIDI IN.|\n+---------------------------+---------------------------------------------------+\n| **Dynamic Software**      | Third-party bundle titles are dynamic and account-|\n|                           | gated. Guaranteed software: Novation Play &amp; Live. |\n+---------------------------+---------------------------------------------------+\n| **Firmware Build Number** | Firmware revisions are dynamic per unit; verify   |\n|                           | via Components Updates.                           |\n+---------------------------+---------------------------------------------------+</pre>"}]},{"type":"step","title":"End of Course Documentation","blocks":[{"type":"prose","html":"The textbook-grade curriculum for <strong>Learning the Launchkey MK4 61</strong> is complete, cited, and fully validated against official Novation engineering specifications."}]}],"minutes":8}],"exercises":[]}]};
